def evidence_window(signals, required):
    need = set(required)
    if not need:
        return [0, 0]
    counts = {}
    left = have = 0
    best = None
    for right, item in enumerate(signals):
        if item in need:
            counts[item] = counts.get(item, 0) + 1
            have += counts[item] == 1
        while have == len(need):
            if best is None or right + 1 - left < best[1] - best[0]:
                best = [left, right + 1]
            removed = signals[left]
            left += 1
            if removed in need:
                counts[removed] -= 1
                have -= counts[removed] == 0
    return best

