import heapq

def least_latency(n, edges, source, target):
    out = [[] for _ in range(n)]
    for a,b,w in edges:
        out[a].append((b,w))
    dist = [float('inf')] * n
    dist[source] = 0
    heap = [(0,source)]
    while heap:
        cost,node = heapq.heappop(heap)
        if cost != dist[node]:
            continue
        if node == target:
            return cost
        for nxt,weight in out[node]:
            candidate = cost + weight
            if candidate < dist[nxt]:
                dist[nxt] = candidate
                heapq.heappush(heap,(candidate,nxt))
    return None

