  for (const [a,b] of links) {
    let x=find(a), y=find(b);
    if (x===y) continue;
    if (size[x]<size[y]) [x,y]=[y,x];
    parent[y]=x; size[x]+=size[y];
  }
  const groups=new Map();
  for (let i=0;i<n;i++) {
    const root=find(i);
    if (!groups.has(root)) groups.set(root,[]);
    groups.get(root).push(i);
  }
  return [...groups.values()];
}

