def split_identifier(text,tokens):
    dictionary = set(tokens)
    n = len(text)
    dp = [float('inf')] * (n+1)
    prev = [-1] * (n+1)
    dp[0] = 0
    for end in range(1,n+1):
        for start in range(end):
            if dp[start]+1 < dp[end] and text[start:end] in dictionary:
                dp[end] = dp[start]+1
                prev[end] = start
    if dp[n] == float('inf'):
        return None
    result = []
    end = n
    while end > 0:
        result.append(text[prev[end]:end])
        end = prev[end]
    return result[::-1]

