def largest_outage(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    seen = set()
    best = 0
    for r in range(rows):
        for c in range(cols):
            if not grid[r][c] or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            count = 0
            while stack:
                x,y = stack.pop()
                count += 1
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b = x+dx,y+dy
                    if 0 <= a < rows and 0 <= b < cols and grid[a][b] and (a,b) not in seen:
                        seen.add((a,b))
                        stack.append((a,b))
            best = max(best,count)
    return best

